// Des: Async cloud sync: records to the cloud DB, raw pages as packs
// Flo: create cloud tables > send record rows in one batch > pack due raw files into 1 archive per run, upload, write manifest, mark done > any failure leaves rows queued with backoff
// I/O: local Db + raw files + Store + Sql (caller) > cloud rows and runs/<date>.pack objects; Sres counts
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const s3v4 = @import("sy-clou-s3v4.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .magi = "SCRAPK1\n", .bodz = 60000, .maxp = 64 << 20, .rawd = "raw" };
pub const Sync = struct { iozz: std.Io, dbzz: *sqli.Db, dirz: []const u8, conf: cfgz.Conf, store: stor.Store, sql: sqlz.Sql };
pub const Sres = struct { recs: u32 = 0, files: u32 = 0, packb: u64 = 0, fail: u32 = 0, pack: []const u8 = "" };
fn urlh(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { return aren.dupe(u8, &hash.hashHex(urlz)); }
fn cutz(text: []const u8) []const u8 { if (text.len <= CF.bodz) return text; var endz: usize = CF.bodz; while (endz > 0 and (text[endz] & 0xC0) == 0x80) endz -= 1; return text[0..endz]; }
fn numz(aren: std.mem.Allocator, valu: i64) ![]const u8 { return std.fmt.allocPrint(aren, "{d}", .{valu}); }
fn recStmts(self: *Sync, aren: std.mem.Allocator, urlz: []const u8, list: *std.ArrayList([]const u8)) !bool { const row = (try inde.pageGet(self.dbzz, aren, urlz)) orelse return false; const rec = (try inde.recoGet(self.dbzz, aren, urlz)) orelse return false; const dial = self.sql.dial; const uh = try sqlz.lit(aren, dial, try urlh(aren, urlz)); const page = [_]sqlz.Col{ .{ .name = "urlh", .valu = uh }, .{ .name = "urlz", .valu = try sqlz.lit(aren, dial, urlz) }, .{ .name = "hexz", .valu = try sqlz.lit(aren, dial, row.hexz) }, .{ .name = "code", .valu = try numz(aren, row.code) }, .{ .name = "tier", .valu = try numz(aren, row.tier) }, .{ .name = "vend", .valu = try sqlz.lit(aren, dial, row.vend) }, .{ .name = "fetc", .valu = try numz(aren, row.fetc) } }; const reco = [_]sqlz.Col{ .{ .name = "urlh", .valu = uh }, .{ .name = "hexz", .valu = try sqlz.lit(aren, dial, rec.hexz) }, .{ .name = "kind", .valu = try sqlz.lit(aren, dial, rec.kind) }, .{ .name = "body", .valu = try sqlz.lit(aren, dial, cutz(rec.body)) }, .{ .name = "timz", .valu = try numz(aren, row.fetc) } }; try list.append(aren, try sqlz.upsert(aren, dial, "cl_page", "urlh", &page)); try list.append(aren, try sqlz.upsert(aren, dial, "cl_reco", "urlh", &reco)); return true; }
fn syncRecs(self: *Sync, aren: std.mem.Allocator, now: i64, res: *Sres) !void { const due = try outb.outbDue(self.dbzz, aren, "rec", now, self.conf.clou_sync_batz); if (due.len == 0) return; var stm: std.ArrayList([]const u8) = .empty; var good: std.ArrayList([]const u8) = .empty; for (due) |item| { if (try recStmts(self, aren, item.keyz, &stm)) try good.append(aren, item.keyz) else try outb.outbDone(self.dbzz, "rec", item.keyz); } if (stm.items.len == 0) return; self.sql.exec(self.sql.ctx, aren, self.iozz, stm.items) catch |err| { for (good.items) |urlz| try outb.outbFail(self.dbzz, "rec", urlz, @errorName(err), now); res.fail += @intCast(good.items.len); return err; }; for (good.items) |urlz| try outb.outbDone(self.dbzz, "rec", urlz); res.recs += @intCast(good.items.len); }
fn syncFiles(self: *Sync, aren: std.mem.Allocator, now: i64, res: *Sres) !void { const due = try outb.outbDue(self.dbzz, aren, "file", now, self.conf.clou_sync_batz); if (due.len == 0) return; var packb: std.ArrayList(u8) = .empty; try packb.appendSlice(aren, CF.magi); const Ent = struct { hexz: []const u8, offs: u64, lenz: u64 }; var ents: std.ArrayList(Ent) = .empty; const rawd = try std.fs.path.join(aren, &.{ self.dirz, CF.rawd }); for (due) |item| { if (!hash.hashOkay(item.keyz)) { try outb.outbFail(self.dbzz, "file", item.keyz, "bad hash", now); continue; } var buff: [96]u8 = undefined; const rela = try hash.hashPath(&buff, item.keyz[0..64].*); const path = try std.fs.path.join(aren, &.{ rawd, rela }); const gz = std.Io.Dir.cwd().readFileAlloc(self.iozz, path, aren, .limited(CF.maxp)) catch { try outb.outbFail(self.dbzz, "file", item.keyz, "local file missing", now); res.fail += 1; continue; }; if (packb.items.len + gz.len > CF.maxp) break; try packb.appendSlice(aren, item.keyz); var lenb: [4]u8 = undefined; std.mem.writeInt(u32, &lenb, @intCast(gz.len), .little); try packb.appendSlice(aren, &lenb); try ents.append(aren, .{ .hexz = item.keyz, .offs = packb.items.len, .lenz = gz.len }); try packb.appendSlice(aren, gz); } if (ents.items.len == 0) return; var dbuf: [16]u8 = undefined; const key = try std.fmt.allocPrint(aren, "runs/{s}-{x}.pack", .{ s3v4.dateNow(&dbuf, now), std.hash.Wyhash.hash(0, packb.items) & 0xffff }); self.store.put(self.store.ctx, aren, self.iozz, key, packb.items) catch |err| { for (ents.items) |ent| try outb.outbFail(self.dbzz, "file", ent.hexz, @errorName(err), now); res.fail += @intCast(ents.items.len); return err; };
var stm: std.ArrayList([]const u8) = .empty; for (ents.items) |ent| { const cols = [_]sqlz.Col{ .{ .name = "hexz", .valu = try sqlz.lit(aren, self.sql.dial, ent.hexz) }, .{ .name = "pack", .valu = try sqlz.lit(aren, self.sql.dial, key) }, .{ .name = "offs", .valu = try numz(aren, @intCast(ent.offs)) }, .{ .name = "lenz", .valu = try numz(aren, @intCast(ent.lenz)) } }; try stm.append(aren, try sqlz.upsert(aren, self.sql.dial, "cl_manif", "hexz", &cols)); } self.sql.exec(self.sql.ctx, aren, self.iozz, stm.items) catch |err| { for (ents.items) |ent| try outb.outbFail(self.dbzz, "file", ent.hexz, @errorName(err), now); res.fail += @intCast(ents.items.len); return err; };
try self.dbzz.exec("BEGIN IMMEDIATE;"); errdefer self.dbzz.exec("ROLLBACK;") catch {}; for (ents.items) |ent| { var ins = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz) VALUES(?1,?2,?3,?4) ON CONFLICT(hexz) DO UPDATE SET packk=?2,offs=?3,lenz=?4;"); defer ins.fini(); try ins.bindText(1, ent.hexz); try ins.bindText(2, key); try ins.bindInt(3, @intCast(ent.offs)); try ins.bindInt(4, @intCast(ent.lenz)); _ = try ins.step(); try outb.outbDone(self.dbzz, "file", ent.hexz); } try self.dbzz.exec("COMMIT;"); res.files += @intCast(ents.items.len); res.packb += packb.items.len; res.pack = key; }
pub fn syncRun(self: *Sync, aren: std.mem.Allocator, now: i64) !Sres { var res: Sres = .{}; self.sql.exec(self.sql.ctx, aren, self.iozz, &sqlz.DDL) catch |err| { res.fail += 1; return err; }; try syncRecs(self, aren, now, &res); try syncFiles(self, aren, now, &res); return res; }
pub fn restore(self: *Sync, aren: std.mem.Allocator, hexz: hash.Hexz) ![]u8 { var stmt = try self.dbzz.prep("SELECT packk,offs,lenz FROM pack WHERE hexz=?1;"); defer stmt.fini(); try stmt.bindText(1, &hexz); if (!try stmt.step()) return error.NotFound; const key = try aren.dupe(u8, stmt.colText(0)); const offs: usize = @intCast(stmt.colInt(1)); const lenz: usize = @intCast(stmt.colInt(2)); const packb = try self.store.get(self.store.ctx, aren, self.iozz, key); if (offs + lenz > packb.len) return error.HashMismatch; const body = try file.gzipOpen(aren, packb[offs .. offs + lenz], CF.maxp); const back = hash.hashHex(body); if (!std.mem.eql(u8, &back, &hexz)) return error.HashMismatch; return body; }
